from pathlib import Path
import json
import subprocess

root = Path('/tmp/photonic-fingerprint')
record = []
for iteration in range(3):
    for name, argument in (('symmetry', []), ('inspection', ['--length', '32', '--sample', '21'])):
        row = {'name': name, 'round': iteration, 'argument': argument}
        for version in (('before', 'after') if iteration % 2 == 0 else ('after', 'before')):
            row[version] = json.loads(subprocess.check_output([str(root / version / name), *argument], text=True))
        record.append(row)
        (root / 'control.json').write_text(json.dumps(record, indent=2))

script.scaling.py:
from pathlib import Path
import json, subprocess, statistics
root = Path('/tmp/photonic-fingerprint')
record = []
for iteration in range(3):
    for width, depth in [(512, 1), (512, 8), (512, 512), (4096, 32)]:
        for replacement in [False, True]:
            argument = ['--width', str(width), '--depth', str(depth), '--length', '32', '--sample', '101'] + (['--replacement'] if replacement else [])
            row = {'width': width, 'depth': depth, 'replacement': replacement, 'round': iteration, 'argument': argument}
            for version in (['before', 'after'] if iteration % 2 == 0 else ['after', 'before']):
                row[version] = json.loads(subprocess.check_output([str(root / version / 'fingerprint'), *argument]))
            assert all(value['fingerprint'] == row['before'][0]['fingerprint'] for version in ['before', 'after'] for value in row[version])
            record.append(row)
            (root / 'scaling.json').write_text(json.dumps(record, indent=2))
            before, after = [statistics.median(value['execution'] for value in row[version]) * 1000 for version in ['before', 'after']]
            print(iteration, width, depth, replacement, round(before, 4), round(after, 4), round(after / before, 3), flush=True)

script.summary.py:
import json
import statistics
from pathlib import Path

root = Path('/tmp/photonic-fingerprint')
acceptance = json.loads((root / 'acceptance.json').read_text())
summary = []
for name in dict.fromkeys(row['name'] for row in acceptance):
    row = [value for value in acceptance if value['name'] == name]
    phase = {}
    for key in ('duration', 'initialization', 'execution', 'reporting', 'serialization', 'release', 'export'):
        if key not in row[0]['before']['measurement'][0]:
            continue
        value = {version: statistics.median(statistics.median(sample[key]['duration'] if isinstance(sample[key], dict) else sample[key] for sample in item[version]['measurement']) for item in row) for version in ('before', 'after')}
        value['ratio'] = value['after'] / value['before']
        value['pass'] = value['ratio'] <= (1.1 if value['before'] < 0.001 else 1.05)
        phase[key] = value
    summary.append({'name': name, 'phase': phase})
(root / 'summary.json').write_text(json.dumps(summary, indent=2))
for row in summary:
    print(row['name'], {key: round(value['ratio'], 3) for key, value in row['phase'].items()}, 'PASS' if all(value['pass'] for value in row['phase'].values()) else 'FAIL')
control = json.loads((root / 'control.json').read_text())
comparison = []
for position in range(12):
    row = [item for item in control if item['name'] == 'symmetry']
    sample = row[0]['before'][position]
    for item in row:
        assert {key: value for key, value in item['before'][position].items() if key != 'median'} == {key: value for key, value in item['after'][position].items() if key != 'median'}
    value = {version: statistics.median(item[version][position]['median'] for item in row) * 1e-6 for version in ('before', 'after')}
    value['ratio'] = value['after'] / value['before']
    value['pass'] = value['ratio'] <= (1.1 if value['before'] < .001 else 1.05)
    comparison.append({'name': 'symmetry', 'sharing': sample['sharing'], 'coherence': sample['coherence'], **value})
row = [item for item in control if item['name'] == 'inspection']
for item in row:
    for sample in zip(item['before']['measurement'], item['after']['measurement']):
        assert {key: value for key, value in sample[0].items() if key != 'execution'} == {key: value for key, value in sample[1].items() if key != 'execution'}
value = {version: statistics.median(statistics.median(sample['execution'] for sample in item[version]['measurement']) for item in row) for version in ('before', 'after')}
value['ratio'] = value['after'] / value['before']
value['pass'] = value['ratio'] <= 1.05
comparison.append({'name': 'inspection', **value})
(root / 'control-summary.json').write_text(json.dumps(comparison, indent=2))
print('control', [(row['name'], round(row['ratio'], 3), row['pass']) for row in comparison])
scaling = json.loads((root / 'scaling.json').read_text())
summary = []
for key in sorted(set((row['width'], row['depth'], row['replacement']) for row in scaling)):
    row = {'width': key[0], 'depth': key[1], 'replacement': key[2]}
    for phase in ('initialization', 'execution'):
        value = {version: statistics.median(statistics.median(sample[phase] for sample in item[version]) for item in scaling if (item['width'], item['depth'], item['replacement']) == key) for version in ('before', 'after')}
        value['ratio'] = value['after'] / value['before']
        value['limit'] = 1.05 if value['before'] >= .001 else 1.1
        value['pass'] = value['ratio'] <= value['limit']
        row[phase] = value
    summary.append(row)
(root / 'scaling-summary.json').write_text(json.dumps(summary, indent=2))
print('scaling', [(row['width'], row['depth'], row['replacement'], round(row['execution']['ratio'], 3), row['execution']['pass']) for row in summary])

