+use std::collections::BTreeMap;
+
+#[derive(Default)]
+pub(super) struct Index {
+    value: crate::population::Set,
+    capture: BTreeMap<usize, usize>,
+}
+
+impl Index {
+    pub fn advance(&self, value: &crate::population::Set) -> Self {
+        let mut capture = self.capture.clone();
+        for position in self.value.removed(value) {
+            let Some(frame) = self.value.at(position).capture else {
+                continue;
+            };
+            let count = capture.get_mut(&frame).unwrap();
+            *count -= 1;
+            if *count == 0 {
+                capture.remove(&frame);
+            }
+        }
+        for position in value.removed(&self.value) {
+            if let Some(frame) = value.at(position).capture {
+                *capture.entry(frame).or_default() += 1;
+            }
+        }
+        Self {
+            value: value.clone(),
+            capture,
+        }
+    }
+
+    pub fn target(&self) -> impl Iterator<Item = usize> + '_ {
+        self.capture.keys().copied()
+    }
+
+    pub fn retained(&self) -> usize {
+        1 + self.capture.len()
+    }
+}
